import json
import math
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    errors = []
    if not isinstance(record, dict):
        return [{"field": "record", "code": "invalid_type", "message": "record must be an object"}]
    for field_name in REQUIRED_FIELDS:
        if field_name not in record or record[field_name] is None:
            errors.append({"field": field_name, "code": "required", "message": f"{field_name} is required"})
    if "amount" in record and record["amount"] is not None:
        amount = record["amount"]
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or not math.isfinite(amount):
            errors.append({"field": "amount", "code": "invalid_type", "message": "amount must be a finite number"})
        elif amount < 0:
            errors.append({"field": "amount", "code": "invalid_range", "message": "amount must be non-negative"})
    return errors


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A missing profile is an expected condition; defaults complete it.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    failures = []
    valid_records = []
    # Complete the local validation pass before touching either service.
    for index, record in enumerate(payload):
        errors = validate_record(record)
        if errors:
            failures.append({"index": index, "payload": record, "errors": errors})
        else:
            valid_records.append((index, record))

    for index, record in valid_records:
        enriched = enrich(record)
        try:
            normalized = normalize(enriched)
        except (KeyError, TypeError, ValueError) as exc:
            failures.append({"index": index, "payload": record, "errors": [
                {"field": "currency", "code": "invalid", "message": str(exc)}
            ]})
            continue
        results.append(send_transaction(normalized))
    return {
        "results": results,
        "failures": failures,
        "counts": {"total": len(payload), "succeeded": len(results), "failed": len(failures)},
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
    }
